function e(e){e.forEach(e=>{e.querySelectorAll("[data-redeem-show]").forEach(e=>{const t=e.getAttribute("data-redeem-show")?.trim();t&&e.querySelectorAll("a[href]").forEach(e=>{const r=new window.URL(e.getAttribute("href"),window.location.origin);"/redemption"===r.pathname.replace(/\/$/,"")&&(r.searchParams.set("show",t),e.setAttribute("href",`${r.pathname}${r.search}`))})})})}export{e as default};
